#include <iostream>
#include <memory>

struct Request {
    int id = 7;

    ~Request() {
        std::cout << "销毁请求\n";
    }
};

int main() {
    {
        auto req = std::make_unique<Request>();
        std::cout << "创建完成\n";
        std::cout << "处理请求 " << req->id << "\n";
    } // A

    std::cout << "块外\n";
} // B
